import {clamp} from '../physics.js';
const angle=(x,y,hand)=>{const degrees=Math.atan2(-y,x*(hand==='left'?-1:1))*180/Math.PI;return degrees===-180?180:degrees;};
const delta=(a,b)=>((a-b+540)%360)-180;
export const GESTURE_TUNING={minimumDistance:.018,minimumDuration:.025,mouseIdle:.12,wheelIdle:.14,typicalSpeed:1.4,typicalLength:.35};
// Samples are normalized to the interaction surface, never stored as pixels.
export class GestureController {
 constructor(){this.calibration={...GESTURE_TUNING};this.reset();}
 reset(){this.samples=[];this.smoothed=[];this.active=false;this.features=null;this.released=false;this.releaseTime=null;}
 begin(x,y,t,hand='right',source='touch'){this.reset();this.hand=hand;this.source=source;this.active=true;this.sample(x,y,t);}
 sample(x,y,t){if(!this.active||!Number.isFinite(x+y+t))return this.features;if(this.samples.length>=4096){this.end(t);return this.features;}const prev=this.samples.at(-1);if(prev&&t<=prev.timestamp)return this.features;const dt=prev?Math.max(.001,t-prev.timestamp):.016,vx=prev?(x-prev.normalizedX)/dt:0,vy=prev?(y-prev.normalizedY)/dt:0;this.samples.push({timestamp:t,normalizedX:x,normalizedY:y,velocityX:vx,velocityY:vy,speed:Math.hypot(vx,vy)});const old=this.smoothed.at(-1),a=1-Math.exp(-dt*45);this.smoothed.push({x:old?old.x+(x-old.x)*a:x,y:old?old.y+(y-old.y)*a:y,t});this.features=this.measure();return this.features;}
 measure(){const p=this.samples,s=this.smoothed,a=p[0],b=p.at(-1),first=s[0],last=s.at(-1),duration=Math.max(.001,b.timestamp-a.timestamp);let distance=0,peak=0,acceleration=0;for(let i=1;i<p.length;i++){distance+=Math.hypot(p[i].normalizedX-p[i-1].normalizedX,p[i].normalizedY-p[i-1].normalizedY);peak=Math.max(peak,p[i].speed);acceleration=Math.max(acceleration,Math.abs(p[i].speed-p[i-1].speed)/Math.max(.001,p[i].timestamp-p[i-1].timestamp));}const initial=s[Math.min(s.length-1,Math.max(1,Math.floor(s.length*.25)))],terminal=s[Math.max(0,Math.floor((s.length-1)*.7))],dx=last.x-first.x,dy=last.y-first.y,initialAngle=angle(initial.x-first.x,initial.y-first.y,this.hand),meanAngle=angle(dx,dy,this.hand),terminalAngle=angle(last.x-terminal.x,last.y-terminal.y,this.hand),terminalDistance=Math.hypot(last.x-terminal.x,last.y-terminal.y),baseDistance=Math.hypot(terminal.x-first.x,terminal.y-first.y),terminalUp=(terminal.y-last.y)/(terminalDistance||1),baseUp=(first.y-terminal.y)/(baseDistance||1),upCurve=clamp(terminalUp-baseUp,0,1),effort=clamp(.22+.55*(peak/this.calibration.typicalSpeed),.22,1),endHeight=1-b.normalizedY;
 return {startPosition:{x:a.normalizedX,y:a.normalizedY},endPosition:{x:b.normalizedX,y:b.normalizedY},totalDistance:distance,normalizedLength:distance/this.calibration.typicalLength*.35,duration,averageVelocity:{x:(b.normalizedX-a.normalizedX)/duration,y:(b.normalizedY-a.normalizedY)/duration},averageSpeed:distance/duration,peakVelocity:peak,initialAngle,averageAngle:meanAngle,terminalAngle,curvature:delta(terminalAngle,initialAngle)/180,terminalCurvature:upCurve,terminalRise:terminal.y-last.y,startHeight:1-a.normalizedY,endHeight,verticalRise:a.normalizedY-b.normalizedY,horizontalDistance:Math.abs(b.normalizedX-a.normalizedX),acceleration,gestureConfidence:clamp(distance/.08,0,1)*clamp(p.length/5,0,1),effort,loft:upCurve*clamp((endHeight-.2)/.55,0,1)*clamp((effort-.4)/.45,0,1),gestureStartTime:a.timestamp,releaseTime:this.releaseTime??null,source:this.source};}
 end(t,cancel=false){if(!this.active)return this.features;this.releaseTime=t;this.active=false;this.released=true;if(this.features){this.features.releaseTime=t;this.features.cancelled=cancel;}return this.features;}
 calibrate(samples){if(samples.length<12)return false;const median=a=>a.sort((x,y)=>x-y)[Math.floor(a.length/2)];this.calibration.typicalSpeed=clamp(median(samples.map(s=>s.peakVelocity)),.4,5);this.calibration.typicalLength=clamp(median(samples.map(s=>s.totalDistance)),.08,.8);this.calibration.range={minX:Math.min(...samples.map(s=>s.startPosition.x)),maxX:Math.max(...samples.map(s=>s.endPosition.x)),minY:Math.min(...samples.map(s=>s.endPosition.y)),maxY:Math.max(...samples.map(s=>s.startPosition.y))};return true;}
}
